import { getLanguage } from '@/lib/i18n';

/**
 * Country names for the numbers the globe's map uses (ISO 3166 numeric), in
 * the app's language: the phone names them itself (`Intl.DisplayNames`) from
 * the two-letter code, so there's nothing to translate.
 */
const CODES =
  '';

const alpha2 = new Map<number, string>();
for (let i = 0; i < CODES.length; i += 5) alpha2.set(Number(CODES.slice(i, i + 3)), CODES.slice(i + 3, i + 5));

let names: Intl.DisplayNames | null | undefined;

/** A country's name in the app's language; its two-letter code if the phone can't name it, its number failing that. */
export function countryName(id: number): string {
  const code = alpha2.get(id);
  if (!code) return `#${id}`;
  if (names === undefined) {
    try {
      names = new Intl.DisplayNames([getLanguage(), 'en'], { type: 'region' });
    } catch {
      names = null;
    }
  }
  try {
    return names?.of(code) ?? code;
  } catch {
    return code;
  }
}
